import{_ as i,I as r,c as n,o,ag as a,J as s}from"./chunks/framework.ARG558ZT.js";const g=JSON.parse('{"title":"Applied AI: evidence, actions and automation","description":"","frontmatter":{},"headers":[],"relativePath":"applied-ai/index.md","filePath":"applied-ai/index.md"}'),d={name:"applied-ai/index.md"};function l(c,e,p,h,u,m){const t=r("MermaidDiagram");return o(),n("div",null,[e[0]||(e[0]=a('<h1 id="applied-ai-evidence-actions-and-automation" tabindex="-1">Applied AI: evidence, actions and automation <a class="header-anchor" href="#applied-ai-evidence-actions-and-automation" aria-label="Permalink to “Applied AI: evidence, actions and automation”">​</a></h1><p>The shared domain is a small <strong>authorized notes catalogue</strong>. A RAG assistant answers from current note spans; a tool workflow may propose a versioned rename; n8n can deliver a bounded refresh event to a custom service. They reuse identities and failure policies without giving retrieved text control over permissions.</p><h2 id="reading-order-and-prerequisites" tabindex="-1">Reading order and prerequisites <a class="header-anchor" href="#reading-order-and-prerequisites" aria-label="Permalink to “Reading order and prerequisites”">​</a></h2><ol><li><a href="./../python-for-ai/">Python prerequisites</a>: typed functions, validation, owned async I/O and service boundaries. The existing JS/TypeScript/Node path remains a useful alternative implementation background.</li><li><a href="./shared/">Shared foundations</a>: model adapter, structured outputs, tools, state, security, budgets, evaluation and safe diagnostics.</li><li><a href="./rag/">RAG</a>: ingestion/provenance → representations/lifecycle → retrieval → checked answers → evaluation and deletion.</li><li><a href="./workflows/">Agent workflows</a>: fixed workflow first, then bounded model proposals, durable artifacts, approvals, receipts and recovery.</li><li><a href="./n8n/">n8n</a>: items/expressions/triggers, bounded service integration, testing/errors and deployment ownership.</li></ol><p>The <a href="./coverage-map.html">coverage map</a> links each requirement to inspected explanations, examples and practice. The <a href="./../practice/applied-ai/">integrated practice sequence</a> refines P-334/P-335 before adding one n8n checkpoint. <strong>All learner practice remains outstanding.</strong> Material completion means usable explanations and specifications, not live model quality or a deployed product.</p><h2 id="separate-the-responsibilities" tabindex="-1">Separate the responsibilities <a class="header-anchor" href="#separate-the-responsibilities" aria-label="Permalink to “Separate the responsibilities”">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Owns</th><th>Must not infer</th></tr></thead><tbody><tr><td>Shared application boundaries</td><td>Authenticated identity, schemas, current permissions, budgets, logs and evaluation policy</td><td>A valid schema is true or authorized</td></tr><tr><td>RAG</td><td>Selecting and attributing current permitted evidence</td><td>Relevance grants tool/action authority</td></tr><tr><td>Agent workflow</td><td>Allowed next steps, persisted progress/artifacts and exact effect recovery</td><td>A model&#39;s plan or claimed approval is permission</td></tr><tr><td>n8n automation</td><td>Trigger/dataflow/integration orchestration under configured credentials</td><td>A canvas or an AI node supplies idempotency, current source ACL or human consent</td></tr></tbody></table>',7)),s(t,{"encoded-source":"flowchart%20TD%0A%20%20%20%20Shared%5BShared%20contracts%20and%20security%5D%20--%3E%20RAG%5BRAG%20evidence%20pipeline%5D%0A%20%20%20%20Shared%20--%3E%20Workflow%5BBounded%20tool%20workflow%5D%0A%20%20%20%20Shared%20--%3E%20Automation%5Bn8n%20integration%5D%0A%20%20%20%20Automation%20--%3E%20API%5BAuthenticated%20custom%20service%5D%0A%20%20%20%20API%20--%3E%20RAG%0A%20%20%20%20API%20--%3E%20Workflow%0A%20%20%20%20RAG%20--%3E%20Data%5BChecked%20evidence%20remains%20data%5D%0A%20%20%20%20Workflow%20--%3E%20Gate%5BCurrent%20authorization%20and%20approval%20gate%5D%0A%20%20%20%20Gate%20--%3E%20Receipt%5BAuthoritative%20effect%20and%20receipt%5D"}),e[1]||(e[1]=a('<h2 id="where-the-material-lives" tabindex="-1">Where the material lives <a class="header-anchor" href="#where-the-material-lives" aria-label="Permalink to “Where the material lives”">​</a></h2><ul><li><code>docs/applied-ai/shared/</code>, <code>rag/</code>, <code>workflows/</code>, <code>n8n/</code>: topic homes and missing integration explanations.</li><li><code>docs/python-for-ai/</code>: established detailed Python lessons, with their existing URLs preserved. Grouped indexes replace the old flat forty-step reading list; there is no second copy of each lesson.</li><li><a href="./../workbench/applied-ai/">Applied-AI workbench</a>: canonical Python source/checks and dependency-complete optional labs; n8n transformation/local-adapter fixtures are separate.</li><li><a href="./../practice/applied-ai/">Practice</a>: staged projects and relocated chapter assignments. Historical author observations remain labeled observations in the textbook.</li></ul><p>Start with lexical search or direct database lookup when it meets the question. Add embeddings, learned reranking, autonomous routing or a visual orchestrator only for a measured need. Multiple agents, PDF/OCR, production ANN and distributed workflow hosting are optional extensions rather than prerequisites.</p>',3))])}const A=i(d,[["render",l]]);export{g as __pageData,A as default};
